#include <Security/Security.h>
#include <CoreFoundation/CoreFoundation.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
int main(int argc,char**argv){if(argc!=3)return 2;CFStringRef service=CFSTR("Portal MCP"),account=CFStringCreateWithCString(NULL,argv[2],kCFStringEncodingUTF8);const void*keys[]={kSecClass,kSecAttrService,kSecAttrAccount};const void*vals[]={kSecClassGenericPassword,service,account};CFMutableDictionaryRef q=CFDictionaryCreateMutable(NULL,0,&kCFTypeDictionaryKeyCallBacks,&kCFTypeDictionaryValueCallBacks);for(int i=0;i<3;i++)CFDictionarySetValue(q,keys[i],vals[i]);OSStatus s=errSecSuccess;if(!strcmp(argv[1],"put")){unsigned char b[4096];size_t n=fread(b,1,sizeof(b),stdin);if(n==0||n==sizeof(b))return 2;CFDataRef data=CFDataCreate(NULL,b,n);CFDictionarySetValue(q,kSecValueData,data);CFDictionarySetValue(q,kSecAttrAccessible,kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly);s=SecItemAdd(q,NULL);if(s==errSecDuplicateItem){CFDictionaryRemoveValue(q,kSecValueData);CFDictionaryRemoveValue(q,kSecAttrAccessible);const void*k[]={kSecValueData};const void*v[]={data};CFDictionaryRef u=CFDictionaryCreate(NULL,k,v,1,&kCFTypeDictionaryKeyCallBacks,&kCFTypeDictionaryValueCallBacks);s=SecItemUpdate(q,u);CFRelease(u);}memset(b,0,sizeof(b));CFRelease(data);}else if(!strcmp(argv[1],"get")){CFDictionarySetValue(q,kSecReturnData,kCFBooleanTrue);CFTypeRef result=NULL;s=SecItemCopyMatching(q,&result);if(s==errSecSuccess){CFDataRef data=(CFDataRef)result;fwrite(CFDataGetBytePtr(data),1,CFDataGetLength(data),stdout);CFRelease(result);}}else if(!strcmp(argv[1],"delete"))s=SecItemDelete(q);else return 2;CFRelease(q);CFRelease(account);if(s!=errSecSuccess){fprintf(stderr,"Keychain operation failed: %d\n",(int)s);return 1;}return 0;}
